const fs=require('fs'),path=require('path'),{execSync}=require('child_process');
const files={"frontend/src/app/(marketing)/about/page.tsx":"import Link from \"next/link\";\nimport { ArrowRight, Globe, Users, TrendingUp, Shield, Code2 } from \"lucide-react\";\nimport type { Metadata } from \"next\";\n\nexport const metadata: Metadata = {\n  title: \"About — DropOS\",\n  description: \"We are building the AI commerce platform. DropOS lets anyone launch a store in 60 seconds.\",\n};\n\nconst C = { navy:\"#130D2E\", purple:\"#6B35E8\", muted:\"rgba(19,13,46,0.5)\", border:\"rgba(107,53,232,0.1)\", faint:\"rgba(107,53,232,0.04)\" };\n\nexport default function AboutPage() {\n  return (\n    <div style={{ fontFamily:\"'Plus Jakarta Sans',system-ui,sans-serif\" }}>\n      <style>{`@import url('https://fonts.googleapis.com/css2?family=Fraunces:ital,wght@0,400;0,500;1,400;1,500&family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&display=swap');`}</style>\n\n      {/* Hero */}\n      <section style={{ textAlign:\"center\", padding:\"80px 24px 64px\", maxWidth:780, margin:\"0 auto\" }}>\n        <p style={{ fontSize:11, fontWeight:700, letterSpacing:\"0.12em\", color:C.purple, marginBottom:12, textTransform:\"uppercase\" }}>ABOUT DROPOS</p>\n        <h1 style={{ fontFamily:\"'Fraunces',Georgia,serif\", fontSize:\"clamp(36px,6vw,60px)\", fontWeight:500, letterSpacing:\"-0.04em\", color:C.navy, margin:\"0 0 20px\", lineHeight:1.08 }}>\n          We are building the<br/><em style={{ fontStyle:\"italic\", color:C.purple }}>AI commerce platform.</em>\n        </h1>\n        <p style={{ fontSize:17, color:C.muted, lineHeight:1.7, maxWidth:540, margin:\"0 auto\" }}>\n          Most people who want to start an online business spend more time fighting tools than actually selling. KIRO fixes that.\n        </p>\n      </section>\n\n      {/* Mission */}\n      <section style={{ maxWidth:1040, margin:\"0 auto\", padding:\"0 24px 80px\", display:\"grid\", gridTemplateColumns:\"1fr 1fr\", gap:64, alignItems:\"center\" }} className=\"about-grid\">\n        <div>\n          <p style={{ fontSize:11, fontWeight:700, letterSpacing:\"0.12em\", color:C.purple, marginBottom:14, textTransform:\"uppercase\" }}>Our Mission</p>\n          <h2 style={{ fontFamily:\"'Fraunces',Georgia,serif\", fontSize:\"clamp(26px,4vw,38px)\", fontWeight:500, color:C.navy, margin:\"0 0 18px\", letterSpacing:\"-0.03em\", lineHeight:1.15 }}>\n            Give every seller the tools big brands take for granted.\n          </h2>\n          <p style={{ fontSize:15, color:C.muted, lineHeight:1.7, marginBottom:14 }}>\n            A seller in Lagos, London, or Nairobi should have access to the same quality of AI, analytics, and automation that enterprise companies have — at a price that makes sense for an independent seller.\n          </p>\n          <p style={{ fontSize:15, color:C.muted, lineHeight:1.7 }}>\n            We are not competing with Shopify on features. We are building something fundamentally different: a platform where the AI does the work, and you do the selling.\n          </p>\n        </div>\n\n        <div style={{ display:\"grid\", gridTemplateColumns:\"1fr 1fr\", gap:12 }}>\n          {[\n            { icon:Globe,      label:\"Global First\",    desc:\"Built for sellers worldwide. Naira, Pounds, Dollars — all supported natively.\" },\n            { icon:Users,      label:\"Seller-Centric\",  desc:\"Every decision is made with the seller's success in mind, not advertisers.\" },\n            { icon:TrendingUp, label:\"Growth Focused\",  desc:\"KIRO spots opportunities and tells you what to do, not just what happened.\" },\n            { icon:Shield,     label:\"Privacy First\",   desc:\"Your store data is yours. We never sell it, share it, or use it to train models.\" },\n          ].map(v => (\n            <div key={v.label} style={{ padding:20, borderRadius:16, background:\"#fff\", border:`1px solid ${C.border}`, boxShadow:\"0 2px 12px rgba(107,53,232,0.04)\" }}>\n              <div style={{ width:36, height:36, borderRadius:10, background:\"rgba(107,53,232,0.08)\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", marginBottom:12 }}>\n                <v.icon size={16} color={C.purple}/>\n              </div>\n              <h3 style={{ fontSize:14, fontWeight:700, color:C.navy, margin:\"0 0 6px\" }}>{v.label}</h3>\n              <p style={{ fontSize:12, color:C.muted, lineHeight:1.6, margin:0 }}>{v.desc}</p>\n            </div>\n          ))}\n        </div>\n      </section>\n\n      {/* Team */}\n      <section style={{ background:\"#fff\", borderTop:`1px solid ${C.border}`, borderBottom:`1px solid ${C.border}`, padding:\"72px 24px\" }}>\n        <div style={{ maxWidth:760, margin:\"0 auto\" }}>\n          <div style={{ textAlign:\"center\", marginBottom:48 }}>\n            <p style={{ fontSize:11, fontWeight:700, letterSpacing:\"0.12em\", color:C.purple, marginBottom:12, textTransform:\"uppercase\" }}>The Team</p>\n            <h2 style={{ fontFamily:\"'Fraunces',Georgia,serif\", fontSize:\"clamp(28px,4vw,42px)\", fontWeight:500, color:C.navy, margin:0, letterSpacing:\"-0.03em\" }}>\n              Built by <em style={{ fontStyle:\"italic\", color:C.purple }}>builders.</em>\n            </h2>\n          </div>\n          <div style={{ display:\"grid\", gridTemplateColumns:\"1fr 1fr\", gap:16 }} className=\"team-grid\">\n            {[\n              {\n                name:\"Olamide A.\", role:\"CTO & Co-founder\", avatar:\"O\",\n                bio:\"Full-stack engineer. Sole technical architect of DropOS. Built the entire platform from zero — AI integration, SaaS infrastructure, and all 29 store templates.\",\n              },\n              {\n                name:\"Tobi B.\", role:\"CEO & Co-founder\", avatar:\"T\",\n                bio:\"Business and growth. Spent years watching sellers struggle with tools built for Silicon Valley. DropOS is the platform he wished existed when he started.\",\n              },\n            ].map(m => (\n              <div key={m.name} style={{ padding:28, borderRadius:20, background:C.faint, border:`1px solid ${C.border}` }}>\n                <div style={{ display:\"flex\", alignItems:\"center\", gap:14, marginBottom:14 }}>\n                  <div style={{ width:48, height:48, borderRadius:14, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", fontWeight:900, fontSize:20, color:\"#fff\", background:\"linear-gradient(145deg,#2D1B69,#0D0625)\", flexShrink:0 }}>\n                    {m.avatar}\n                  </div>\n                  <div>\n                    <p style={{ fontSize:15, fontWeight:800, color:C.navy, margin:0, letterSpacing:\"-0.01em\" }}>{m.name}</p>\n                    <p style={{ fontSize:12, color:C.purple, margin:0, fontWeight:600 }}>{m.role}</p>\n                  </div>\n                </div>\n                <p style={{ fontSize:13, color:C.muted, lineHeight:1.65, margin:0 }}>{m.bio}</p>\n              </div>\n            ))}\n          </div>\n        </div>\n      </section>\n\n      {/* Values */}\n      <section style={{ padding:\"72px 24px\", maxWidth:1040, margin:\"0 auto\" }}>\n        <div style={{ textAlign:\"center\", marginBottom:48 }}>\n          <p style={{ fontSize:11, fontWeight:700, letterSpacing:\"0.12em\", color:C.purple, marginBottom:12, textTransform:\"uppercase\" }}>What We Believe</p>\n          <h2 style={{ fontFamily:\"'Fraunces',Georgia,serif\", fontSize:\"clamp(28px,4vw,42px)\", fontWeight:500, color:C.navy, margin:0, letterSpacing:\"-0.03em\" }}>\n            Our <em style={{ fontStyle:\"italic\", color:C.purple }}>values.</em>\n          </h2>\n        </div>\n        <div style={{ display:\"grid\", gridTemplateColumns:\"repeat(3,1fr)\", gap:16 }} className=\"values-grid\">\n          {[\n            { n:\"01\", title:\"Commerce should be accessible\", desc:\"The barrier to starting an online business should be zero — not a $300/month Shopify bill and a design degree.\" },\n            { n:\"02\", title:\"AI should do the work\", desc:\"You should not have to write product descriptions, optimize prices, or figure out abandoned carts manually. KIRO handles it.\" },\n            { n:\"03\", title:\"Sellers deserve transparency\", desc:\"No hidden fees. No confusing tiers. No bait-and-switch. What you see is what you pay.\" },\n          ].map(v => (\n            <div key={v.n} style={{ padding:28, borderRadius:20, background:\"#fff\", border:`1px solid ${C.border}` }}>\n              <span style={{ fontSize:11, fontWeight:800, color:C.purple, letterSpacing:\"0.1em\", display:\"block\", marginBottom:12 }}>{v.n}</span>\n              <h3 style={{ fontSize:16, fontWeight:700, color:C.navy, margin:\"0 0 10px\", letterSpacing:\"-0.02em\", lineHeight:1.3 }}>{v.title}</h3>\n              <p style={{ fontSize:13, color:C.muted, lineHeight:1.65, margin:0 }}>{v.desc}</p>\n            </div>\n          ))}\n        </div>\n      </section>\n\n      {/* CTA */}\n      <section style={{ padding:\"80px 24px\", textAlign:\"center\", background:\"linear-gradient(160deg,#2D1B69,#0D0625)\" }}>\n        <h2 style={{ fontFamily:\"'Fraunces',Georgia,serif\", fontSize:\"clamp(28px,5vw,48px)\", fontWeight:500, color:\"#fff\", margin:\"0 0 14px\", letterSpacing:\"-0.03em\" }}>\n          Join us.\n        </h2>\n        <p style={{ fontSize:16, color:\"rgba(255,255,255,0.5)\", marginBottom:36, maxWidth:400, margin:\"0 auto 36px\" }}>\n          Thousands of merchants are launching stores with DropOS every week. Be next.\n        </p>\n        <Link href=\"/auth/register\" style={{ display:\"inline-flex\", alignItems:\"center\", gap:8, padding:\"14px 32px\", borderRadius:14, background:\"#fff\", color:C.navy, textDecoration:\"none\", fontSize:14, fontWeight:700, boxShadow:\"0 8px 24px rgba(0,0,0,0.2)\" }}>\n          Start for free <ArrowRight size={14}/>\n        </Link>\n      </section>\n\n      <style>{`\n        @media(max-width:768px){\n          .about-grid,.team-grid{grid-template-columns:1fr!important;}\n          .values-grid{grid-template-columns:1fr!important;}\n        }\n      `}</style>\n    </div>\n  );\n}\n","frontend/src/app/(marketing)/features/page.tsx":"import Link from \"next/link\";\nimport { Zap, Globe, ShoppingCart, BarChart2, Package, Cpu, Shield, Truck, Image, Video, Users, ArrowRight, Check } from \"lucide-react\";\n\nexport const metadata = { title: \"Features — DropOS\", description: \"Everything you need to build and run a successful online store.\" };\n\nconst SECTIONS = [\n  {\n    tag: \"AI POWERED\",\n    title: \"KIRO — Your AI Business Partner\",\n    desc: \"Not a chatbot. A full business operator that builds, manages, and grows your store.\",\n    color: \"#8B5CF6\",\n    features: [\n      \"Build a complete store from one sentence\",\n      \"Write product descriptions and ad copy\",\n      \"Find trending products before they peak\",\n      \"Manage orders and customer messages\",\n      \"Monitor competitor prices and alert you\",\n      \"Generate TikTok scripts for any product\",\n      \"Revenue forecasting and anomaly detection\",\n      \"Morning briefings with actionable insights\",\n    ],\n  },\n  {\n    tag: \"COMMERCE\",\n    title: \"Everything built in. Nothing to install.\",\n    desc: \"Shopify charges extra for every feature. DropOS includes it all.\",\n    color: \"#06B6D4\",\n    features: [\n      \"Unlimited products and variants\",\n      \"20+ professional store templates\",\n      \"Custom domain connection\",\n      \"Coupons, flash sales, gift cards\",\n      \"Loyalty points programme\",\n      \"Abandoned cart recovery\",\n      \"Customer reviews and ratings\",\n      \"Affiliate programme for your store\",\n    ],\n  },\n  {\n    tag: \"PAYMENTS\",\n    title: \"Accept payment anywhere in the world.\",\n    desc: \"Every major payment method. No friction. No lost sales.\",\n    color: \"#10B981\",\n    features: [\n      \"Paystack (Nigeria, Ghana, South Africa)\",\n      \"Stripe (Global, 135+ currencies)\",\n      \"Flutterwave (Africa-wide)\",\n      \"Apple Pay and Google Pay\",\n      \"Pay on Delivery\",\n      \"Buy now, pay later (Klarna, Carbon)\",\n      \"Cryptocurrency (USDT, USDC)\",\n      \"Automatic currency conversion\",\n    ],\n  },\n  {\n    tag: \"FULFILMENT\",\n    title: \"Orders fulfilled automatically.\",\n    desc: \"KIRO connects to suppliers, places orders, and tracks shipments. You do nothing.\",\n    color: \"#F59E0B\",\n    features: [\n      \"AliExpress auto-import and order\",\n      \"CJDropshipping integration\",\n      \"Zendrop and Spocket connect\",\n      \"Auto tracking number import\",\n      \"Customer shipping notifications\",\n      \"Delay detection and alerts\",\n      \"DHL, FedEx, UPS, Royal Mail\",\n      \"GIG Logistics, Sendbox (Nigeria)\",\n    ],\n  },\n  {\n    tag: \"CONTENT STUDIO\",\n    title: \"Professional content. No team needed.\",\n    desc: \"AI-generated images, videos, and ads that actually convert.\",\n    color: \"#EC4899\",\n    features: [\n      \"Background removal in one click\",\n      \"Lifestyle scene generation\",\n      \"TikTok and Reels video scripts\",\n      \"AI-generated ad creatives\",\n      \"Auto-caption for all platforms\",\n      \"Smart crop for every format\",\n      \"Social media scheduling\",\n      \"30-day content calendar\",\n    ],\n  },\n  {\n    tag: \"ANALYTICS\",\n    title: \"Know exactly what drives your sales.\",\n    desc: \"Real data. Plain English. KIRO overlaid on every chart.\",\n    color: \"#6B35E8\",\n    features: [\n      \"Revenue, orders, and customer LTV\",\n      \"Cohort and retention analysis\",\n      \"Geographic heat map\",\n      \"Revenue attribution by source\",\n      \"Product return rate tracking\",\n      \"Ad spend ROI tracking\",\n      \"Funnel analysis\",\n      \"KIRO insights on every chart\",\n    ],\n  },\n];\n\nexport default function FeaturesPage() {\n  return (\n    <div style={{ background: \"#F4F2FB\", color: \"#130D2E\", fontFamily: \"'Plus Jakarta Sans', system-ui, sans-serif\" }}>\n      <style>{`@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&display=swap');`}</style>\n\n      {/* Nav */}\n{/* Hero */}\n      <div className=\"text-center px-6 py-24\">\n        <p className=\"text-xs font-bold tracking-widest uppercase mb-3\" style={{ color: \"#8B5CF6\" }}>Features</p>\n        <h1 className=\"font-black mb-4\" style={{ fontSize: \"clamp(36px,5vw,64px)\", letterSpacing: \"-2px\" }}>\n          One platform.<br />Everything included.\n        </h1>\n        <p className=\"text-base max-w-xl mx-auto mb-8\" style={{ color:\"rgba(19,13,46,0.5)\" }}>\n          Shopify charges $79/month then nickels and dimes you for every feature. DropOS includes everything — powered by KIRO so it actually runs itself.\n        </p>\n        <Link href=\"/auth/register\">\n          <button className=\"inline-flex items-center gap-2 px-6 py-3 rounded-xl font-bold text-white\" style={{ background: \"linear-gradient(135deg,#6B35E8,#3D1C8A)\", boxShadow: \"0 8px 32px rgba(107,53,232,0.4)\" }}>\n            Start free — no credit card <ArrowRight size={14} />\n          </button>\n        </Link>\n      </div>\n\n      {/* Feature sections */}\n      <div className=\"max-w-5xl mx-auto px-6 space-y-20 pb-24\">\n        {SECTIONS.map((section, i) => (\n          <div key={section.tag} className={`grid md:grid-cols-2 gap-12 items-center ${i % 2 === 1 ? \"md:[direction:rtl]\" : \"\"}`}>\n            <div style={{ direction: \"ltr\" }}>\n              <span className=\"text-xs font-black tracking-widest uppercase mb-3 block\" style={{ color: section.color }}>{section.tag}</span>\n              <h2 className=\"font-black text-2xl sm:text-3xl mb-4 text-white\" style={{ letterSpacing: \"-1px\" }}>{section.title}</h2>\n              <p className=\"text-sm mb-6 leading-relaxed\" style={{ color:\"rgba(19,13,46,0.5)\" }}>{section.desc}</p>\n              <Link href=\"/auth/register\">\n                <button className=\"flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-bold text-white\" style={{ background: `linear-gradient(135deg,${section.color},${section.color}99)` }}>\n                  Get started <ArrowRight size={13} />\n                </button>\n              </Link>\n            </div>\n            <div className=\"p-6 rounded-2xl\" style={{ background: \"rgba(107,53,232,0.03)\", border: `1px solid ${section.color}25`, direction: \"ltr\" }}>\n              <div className=\"grid grid-cols-1 gap-2.5\">\n                {section.features.map(f => (\n                  <div key={f} className=\"flex items-center gap-3\">\n                    <div className=\"w-5 h-5 rounded-full flex items-center justify-center flex-shrink-0\" style={{ background: `${section.color}20` }}>\n                      <Check size={10} style={{ color: section.color }} strokeWidth={3} />\n                    </div>\n                    <span className=\"text-sm\" style={{ color:\"rgba(19,13,46,0.75)\" }}>{f}</span>\n                  </div>\n                ))}\n              </div>\n            </div>\n          </div>\n        ))}\n      </div>\n\n      {/* CTA */}\n      <div className=\"text-center px-6 py-20\" style={{ borderTop: \"1px solid rgba(107,53,232,0.07)\" }}>\n        <h2 className=\"font-black text-3xl sm:text-5xl mb-4\" style={{ letterSpacing: \"-2px\" }}>Ready to start?</h2>\n        <p className=\"text-base mb-8\" style={{ color:\"rgba(19,13,46,0.5)\" }}>Free forever. No credit card. Launch in 60 seconds.</p>\n        <Link href=\"/auth/register\">\n          <button className=\"inline-flex items-center gap-2 px-8 py-4 rounded-xl font-bold text-white text-base\" style={{ background: \"linear-gradient(135deg,#6B35E8,#3D1C8A)\", boxShadow: \"0 12px 40px rgba(107,53,232,0.4)\" }}>\n            Launch your store <ArrowRight size={16} />\n          </button>\n        </Link>\n      </div>\n    </div>\n  );\n}\n","frontend/src/app/(marketing)/contact/page.tsx":"\"use client\";\nimport { useState } from \"react\";\nimport Link from \"next/link\";\nimport { Zap, Mail, MessageSquare, ArrowRight, Check, Loader2 } from \"lucide-react\";\n\nconst API = process.env.NEXT_PUBLIC_API_URL || \"https://dropos-v2.onrender.com/api\";\n\nexport default function ContactPage() {\n  const [form, setForm]   = useState({ name: \"\", email: \"\", subject: \"general\", message: \"\" });\n  const [status, setStatus] = useState<\"idle\"|\"loading\"|\"success\"|\"error\">(\"idle\");\n\n  const set = (k: string, v: string) => setForm(p => ({ ...p, [k]: v }));\n\n  const submit = async () => {\n    if (!form.name || !form.email || !form.message) return;\n    setStatus(\"loading\");\n    try {\n      await fetch(`${API}/contact`, {\n        method: \"POST\", headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify(form),\n      });\n      setStatus(\"success\");\n    } catch {\n      setStatus(\"error\");\n    }\n  };\n\n  const inp = \"w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-sm text-white placeholder-white/25 outline-none focus:border-violet-500/60 transition-all\";\n\n  return (\n    <div style={{ background: \"#F4F2FB\", color: \"#130D2E\", fontFamily: \"'Plus Jakarta Sans', system-ui, sans-serif\" }}>\n      <style>{`@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&display=swap');`}</style>\n<div className=\"max-w-4xl mx-auto px-6 py-20\">\n        <div className=\"text-center mb-14\">\n          <p className=\"text-xs font-bold tracking-widest uppercase mb-3\" style={{ color: \"#8B5CF6\" }}>Contact</p>\n          <h1 className=\"font-black text-4xl sm:text-5xl mb-4\" style={{ letterSpacing: \"-2px\" }}>Get in touch</h1>\n          <p className=\"text-base\" style={{ color:\"rgba(19,13,46,0.5)\" }}>We reply within 24 hours. For urgent issues, message KIRO in your dashboard.</p>\n        </div>\n\n        <div className=\"grid md:grid-cols-3 gap-10\">\n          {/* Contact options */}\n          <div className=\"space-y-4\">\n            {[\n              { icon: MessageSquare, label: \"General questions\", desc: \"Product, pricing, plans\", color: \"#8B5CF6\" },\n              { icon: Zap,           label: \"Technical support\", desc: \"Bugs, errors, help\",       color: \"#06B6D4\" },\n              { icon: Mail,          label: \"Enterprise\",        desc: \"Custom plans, API access\", color: \"#10B981\" },\n            ].map(c => (\n              <div key={c.label} className=\"p-4 rounded-2xl\" style={{ background: \"rgba(107,53,232,0.03)\", border: \"1px solid rgba(107,53,232,0.08)\" }}>\n                <div className=\"w-9 h-9 rounded-xl flex items-center justify-center mb-3\" style={{ background: `${c.color}15` }}>\n                  <c.icon size={16} style={{ color: c.color }} />\n                </div>\n                <h3 className=\"font-bold text-sm text-white mb-1\">{c.label}</h3>\n                <p className=\"text-xs\" style={{ color:\"rgba(19,13,46,0.5)\" }}>{c.desc}</p>\n              </div>\n            ))}\n            <div className=\"p-4 rounded-2xl\" style={{ background: \"rgba(107,53,232,0.08)\", border: \"1px solid rgba(107,53,232,0.2)\" }}>\n              <p className=\"text-xs font-semibold mb-1\" style={{ color: \"#A78BFA\" }}>Fastest response</p>\n              <p className=\"text-xs\" style={{ color:\"rgba(19,13,46,0.5)\" }}>Message KIRO in your dashboard. It knows every feature and can fix most issues instantly.</p>\n              <Link href=\"/auth/login\" className=\"inline-flex items-center gap-1.5 mt-2 text-xs font-bold\" style={{ color: \"#A78BFA\" }}>\n                Open KIRO <ArrowRight size={10} />\n              </Link>\n            </div>\n          </div>\n\n          {/* Form */}\n          <div className=\"md:col-span-2\">\n            {status === \"success\" ? (\n              <div className=\"p-8 rounded-2xl text-center\" style={{ background: \"rgba(16,185,129,0.08)\", border: \"1px solid rgba(16,185,129,0.25)\" }}>\n                <Check size={40} className=\"mx-auto mb-4\" style={{ color: \"#10B981\" }} />\n                <h3 className=\"font-bold text-lg text-white mb-2\">Message sent</h3>\n                <p style={{ color:\"rgba(19,13,46,0.5)\" }}>We'll reply within 24 hours.</p>\n              </div>\n            ) : (\n              <div className=\"space-y-4\">\n                <div className=\"grid grid-cols-2 gap-4\">\n                  <div>\n                    <label className=\"block text-xs font-semibold mb-1.5\" style={{ color:\"rgba(19,13,46,0.5)\" }}>Name</label>\n                    <input value={form.name} onChange={e => set(\"name\", e.target.value)} placeholder=\"Your name\" className={inp} />\n                  </div>\n                  <div>\n                    <label className=\"block text-xs font-semibold mb-1.5\" style={{ color:\"rgba(19,13,46,0.5)\" }}>Email</label>\n                    <input value={form.email} onChange={e => set(\"email\", e.target.value)} type=\"email\" placeholder=\"you@example.com\" className={inp} />\n                  </div>\n                </div>\n                <div>\n                  <label className=\"block text-xs font-semibold mb-1.5\" style={{ color:\"rgba(19,13,46,0.5)\" }}>Subject</label>\n                  <select value={form.subject} onChange={e => set(\"subject\", e.target.value)} className={inp} style={{ cursor: \"pointer\" }}>\n                    <option value=\"general\">General question</option>\n                    <option value=\"support\">Technical support</option>\n                    <option value=\"billing\">Billing issue</option>\n                    <option value=\"enterprise\">Enterprise enquiry</option>\n                    <option value=\"partnership\">Partnership</option>\n                  </select>\n                </div>\n                <div>\n                  <label className=\"block text-xs font-semibold mb-1.5\" style={{ color:\"rgba(19,13,46,0.5)\" }}>Message</label>\n                  <textarea value={form.message} onChange={e => set(\"message\", e.target.value)} rows={5} placeholder=\"How can we help?\" className={inp} style={{ resize: \"none\" }} />\n                </div>\n                <button onClick={submit} disabled={!form.name||!form.email||!form.message||status===\"loading\"}\n                  className=\"w-full flex items-center justify-center gap-2 py-3 rounded-xl text-sm font-bold text-white transition-all disabled:opacity-50\"\n                  style={{ background: \"linear-gradient(135deg,#6B35E8,#3D1C8A)\" }}>\n                  {status===\"loading\" ? <><Loader2 size={14} className=\"animate-spin\" />Sending</> : \"Send message\"}\n                </button>\n                {status===\"error\" && <p className=\"text-xs text-center text-red-400\">Something went wrong. Try again or email hello@droposhq.com</p>}\n              </div>\n            )}\n          </div>\n        </div>\n      </div>\n    </div>\n  );\n}\n","frontend/src/app/(marketing)/pricing/page.tsx":"\"use client\";\nimport { useState, useEffect } from \"react\";\nimport Link from \"next/link\";\nimport { Check, X, ArrowRight, Zap } from \"lucide-react\";\n\nconst C = { bg:\"#F4F2FB\", navy:\"#130D2E\", purple:\"#6B35E8\", muted:\"rgba(19,13,46,0.5)\", border:\"rgba(107,53,232,0.1)\", faint:\"rgba(107,53,232,0.04)\" };\n\nconst CURRENCIES: Record<string,{symbol:string;growth:number;pro:number;locale:string}> = {\n  NGN: { symbol:\"₦\", growth:9500,   pro:25000,  locale:\"en-NG\" },\n  USD: { symbol:\"$\", growth:6,      pro:16,     locale:\"en-US\" },\n  GBP: { symbol:\"£\", growth:5,      pro:14,     locale:\"en-GB\" },\n  GHS: { symbol:\"₵\", growth:89,     pro:240,    locale:\"en-GH\" },\n  KES: { symbol:\"KSh\",growth:1300,  pro:3500,   locale:\"en-KE\" },\n};\n\nfunction detectCurrency(): string {\n  if(typeof window===\"undefined\") return \"USD\";\n  try {\n    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone;\n    if(tz.includes(\"Lagos\")||tz.includes(\"Abuja\")) return \"NGN\";\n    if(tz.includes(\"Accra\")) return \"GHS\";\n    if(tz.includes(\"Nairobi\")) return \"KES\";\n    if(tz.includes(\"London\")) return \"GBP\";\n  } catch {}\n  return \"USD\";\n}\n\nfunction fmt(n:number, code:string) {\n  const c = CURRENCIES[code];\n  return `${c.symbol}${n.toLocaleString()}`;\n}\n\nexport default function PricingPage() {\n  const [currency, setCurrency] = useState(\"USD\");\n  const [annual, setAnnual] = useState(false);\n  useEffect(()=>{ setCurrency(detectCurrency()); },[]);\n\n  const cur = CURRENCIES[currency];\n  const mult = annual ? 0.8 : 1;\n\n  const plans = [\n    {\n      name:\"Free\", tag:\"Try it, no commitment.\",\n      price:\"0\", period:\"/mo\",\n      cta:\"Start free\", ctaHref:\"/auth/register\", highlight:false,\n      features:[\n        {t:\"1 store\",ok:true},{t:\"20 products\",ok:true},\n        {t:\"KIRO — 10 messages/day\",ok:true},{t:\"Basic analytics\",ok:true},\n        {t:\"Paystack payments\",ok:true},{t:\"2% transaction fee\",ok:false},\n        {t:\"Custom domain\",ok:false},{t:\"Email campaigns\",ok:false},\n      ],\n    },\n    {\n      name:\"Growth\", tag:\"For serious sellers.\",\n      price:Math.round(cur.growth*mult).toLocaleString(), period:\"/mo\",\n      trial:\"14-day free trial\",\n      cta:\"Start 14-day trial\", ctaHref:\"/auth/register\", highlight:true,\n      features:[\n        {t:\"5 stores\",ok:true},{t:\"Unlimited products\",ok:true},\n        {t:\"Full KIRO — unlimited\",ok:true},{t:\"Full analytics\",ok:true},\n        {t:\"Paystack + Stripe\",ok:true},{t:\"0% transaction fee\",ok:true},\n        {t:\"Custom domain\",ok:true},{t:\"Coupons & flash sales\",ok:true},\n        {t:\"Abandoned cart recovery\",ok:true},{t:\"Email campaigns\",ok:true},\n      ],\n    },\n    {\n      name:\"Pro\", tag:\"Fully automated business.\",\n      price:Math.round(cur.pro*mult).toLocaleString(), period:\"/mo\",\n      cta:\"Start Pro\", ctaHref:\"/auth/register\", highlight:false,\n      features:[\n        {t:\"Unlimited stores\",ok:true},{t:\"Everything in Growth\",ok:true},\n        {t:\"KIRO Pro intelligence\",ok:true},{t:\"API access\",ok:true},\n        {t:\"3 staff accounts\",ok:true},{t:\"Priority support (2hr)\",ok:true},\n        {t:\"20% referral commissions\",ok:true},{t:\"White label option\",ok:true},\n      ],\n    },\n  ];\n\n  const faqs = [\n    [\"Can I change plans anytime?\",\"Yes. Upgrade or downgrade any time from your billing settings. Changes take effect immediately.\"],\n    [\"Is there a free trial?\",\"The Growth plan comes with a 14-day free trial. No card required to start.\"],\n    [\"What is the 2% transaction fee?\",\"On the Free plan, DropOS takes 2% of every order value. Growth and Pro plans have 0% transaction fees — you keep everything.\"],\n    [\"Do you support currencies other than NGN?\",\"Yes. DropOS supports 50+ currencies. Accept Naira, Pounds, Dollars, Cedis, and more.\"],\n    [\"Can I cancel anytime?\",\"Yes. Cancel from your dashboard with no penalties. You keep access until the end of your billing period.\"],\n    [\"What payment methods do you support?\",\"Paystack (card, bank transfer, USSD) for African payments. Stripe for international card payments.\"],\n  ];\n\n  return (\n    <div style={{ fontFamily:\"'Plus Jakarta Sans',system-ui,sans-serif\" }}>\n      <style>{`@import url('https://fonts.googleapis.com/css2?family=Fraunces:ital,wght@0,400;0,500;1,400;1,500&family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&display=swap');`}</style>\n\n      {/* Hero */}\n      <section style={{ padding:\"80px 24px 60px\", textAlign:\"center\", maxWidth:700, margin:\"0 auto\" }}>\n        <p style={{ fontSize:11, fontWeight:700, letterSpacing:\"0.12em\", color:C.purple, marginBottom:12, textTransform:\"uppercase\" }}>PRICING</p>\n        <h1 style={{ fontFamily:\"'Fraunces',Georgia,serif\", fontSize:\"clamp(36px,6vw,56px)\", fontWeight:500, letterSpacing:\"-0.04em\", color:C.navy, margin:\"0 0 16px\", lineHeight:1.08 }}>\n          Simple, honest<br/><em style={{ fontStyle:\"italic\", color:C.purple }}>pricing.</em>\n        </h1>\n        <p style={{ fontSize:16, color:C.muted, maxWidth:420, margin:\"0 auto 32px\", lineHeight:1.6 }}>\n          No hidden fees. No lock-in. Start free and grow at your pace.\n        </p>\n\n        {/* Toggles */}\n        <div style={{ display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:16, flexWrap:\"wrap\" }}>\n          {/* Currency selector */}\n          <div style={{ display:\"flex\", background:\"#fff\", borderRadius:10, padding:4, border:`1px solid ${C.border}`, gap:2 }}>\n            {Object.keys(CURRENCIES).map(c => (\n              <button key={c} onClick={()=>setCurrency(c)}\n                style={{ padding:\"6px 12px\", borderRadius:7, border:\"none\", cursor:\"pointer\", fontSize:12, fontWeight:700, fontFamily:\"inherit\", background:currency===c ? C.navy : \"transparent\", color:currency===c ? \"#fff\" : C.muted, transition:\"all 0.15s\" }}>\n                {c}\n              </button>\n            ))}\n          </div>\n          {/* Annual toggle */}\n          <div style={{ display:\"flex\", alignItems:\"center\", gap:8, background:\"#fff\", borderRadius:10, padding:\"8px 14px\", border:`1px solid ${C.border}` }}>\n            <span style={{ fontSize:12, fontWeight:600, color:C.muted }}>Monthly</span>\n            <button onClick={()=>setAnnual(!annual)}\n              style={{ width:40, height:22, borderRadius:11, border:\"none\", cursor:\"pointer\", background:annual?C.purple:\"rgba(19,13,46,0.12)\", position:\"relative\", transition:\"background 0.2s\", padding:0 }}>\n              <div style={{ position:\"absolute\", top:3, left:annual?21:3, width:16, height:16, borderRadius:\"50%\", background:\"#fff\", transition:\"left 0.2s\", boxShadow:\"0 1px 3px rgba(0,0,0,0.15)\" }}/>\n            </button>\n            <span style={{ fontSize:12, fontWeight:600, color:annual?C.purple:C.muted }}>Annual <span style={{ background:\"rgba(107,53,232,0.1)\", color:C.purple, padding:\"1px 6px\", borderRadius:4, fontSize:10, fontWeight:700 }}>-20%</span></span>\n          </div>\n        </div>\n      </section>\n\n      {/* Plans */}\n      <section style={{ maxWidth:1040, margin:\"0 auto\", padding:\"0 24px 80px\", display:\"grid\", gridTemplateColumns:\"repeat(3,1fr)\", gap:16 }} className=\"plans-grid\">\n        {plans.map(plan => (\n          <div key={plan.name} style={{\n            background:plan.highlight?\"linear-gradient(160deg,#2D1B69,#1A0B4A)\":\"#fff\",\n            borderRadius:20, padding:\"32px 28px\",\n            border:plan.highlight?\"1px solid rgba(196,181,253,0.3)\":`1px solid ${C.border}`,\n            position:\"relative\",\n            boxShadow:plan.highlight?\"0 20px 60px rgba(45,27,105,0.25)\":\"0 2px 16px rgba(107,53,232,0.06)\",\n          }}>\n            {plan.highlight && (\n              <div style={{ position:\"absolute\", top:-13, left:\"50%\", transform:\"translateX(-50%)\", background:\"#C4B5FD\", color:\"#130D2E\", fontSize:10, fontWeight:800, padding:\"4px 16px\", borderRadius:99, whiteSpace:\"nowrap\", letterSpacing:\"0.06em\" }}>\n                MOST POPULAR\n              </div>\n            )}\n            <p style={{ fontSize:20, fontWeight:800, color:plan.highlight?\"#fff\":C.navy, margin:\"0 0 4px\", letterSpacing:\"-0.02em\" }}>{plan.name}</p>\n            <p style={{ fontSize:13, color:plan.highlight?\"rgba(255,255,255,0.55)\":C.muted, margin:\"0 0 20px\" }}>{plan.tag}</p>\n            <div style={{ display:\"flex\", alignItems:\"baseline\", gap:4, marginBottom:4 }}>\n              <span style={{ fontSize:13, fontWeight:700, color:plan.highlight?\"rgba(255,255,255,0.6)\":C.muted }}>{cur.symbol}</span>\n              <span style={{ fontSize:40, fontWeight:900, color:plan.highlight?\"#fff\":C.navy, letterSpacing:\"-0.04em\" }}>{plan.price}</span>\n              <span style={{ fontSize:13, color:plan.highlight?\"rgba(255,255,255,0.4)\":C.muted }}>{plan.period}</span>\n            </div>\n            {plan.trial && <p style={{ fontSize:12, color:\"#A78BFA\", fontWeight:700, margin:\"0 0 20px\" }}>{plan.trial}</p>}\n            {!plan.trial && <div style={{ height:20, marginBottom:20 }}/>}\n\n            <div style={{ borderTop:`1px solid ${plan.highlight?\"rgba(255,255,255,0.1)\":C.border}`, paddingTop:20, marginBottom:24 }}>\n              {plan.features.map(f => (\n                <div key={f.t} style={{ display:\"flex\", alignItems:\"center\", gap:8, marginBottom:10 }}>\n                  {f.ok\n                    ? <Check size={13} color={plan.highlight?\"#A78BFA\":C.purple} strokeWidth={2.5}/>\n                    : <X size={13} color={plan.highlight?\"rgba(255,255,255,0.2)\":\"rgba(19,13,46,0.2)\"} strokeWidth={2}/>\n                  }\n                  <span style={{ fontSize:13, color:f.ok?(plan.highlight?\"rgba(255,255,255,0.85)\":C.navy):(plan.highlight?\"rgba(255,255,255,0.3)\":\"rgba(19,13,46,0.3)\"), textDecoration:f.ok?\"none\":\"line-through\" }}>\n                    {f.t}\n                  </span>\n                </div>\n              ))}\n            </div>\n\n            <Link href={plan.ctaHref} style={{\n              display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:6,\n              padding:\"13px 0\", borderRadius:12, textDecoration:\"none\",\n              fontSize:14, fontWeight:700,\n              background:plan.highlight?\"#fff\":\"transparent\",\n              color:plan.highlight?C.navy:C.navy,\n              border:plan.highlight?\"none\":`1px solid ${C.border}`,\n            }}>\n              {plan.cta} {plan.highlight && <ArrowRight size={14}/>}\n            </Link>\n          </div>\n        ))}\n      </section>\n\n      {/* FAQ */}\n      <section style={{ maxWidth:720, margin:\"0 auto\", padding:\"0 24px 100px\" }}>\n        <h2 style={{ fontFamily:\"'Fraunces',Georgia,serif\", fontSize:\"clamp(28px,4vw,40px)\", fontWeight:500, color:C.navy, textAlign:\"center\", margin:\"0 0 48px\", letterSpacing:\"-0.03em\" }}>\n          Common <em style={{ fontStyle:\"italic\", color:C.purple }}>questions</em>\n        </h2>\n        <div style={{ display:\"flex\", flexDirection:\"column\", gap:2 }}>\n          {faqs.map(([q, a]) => (\n            <details key={q} style={{ background:\"#fff\", borderRadius:14, border:`1px solid ${C.border}`, overflow:\"hidden\" }}>\n              <summary style={{ padding:\"18px 20px\", fontSize:14, fontWeight:700, color:C.navy, cursor:\"pointer\", listStyle:\"none\", display:\"flex\", justifyContent:\"space-between\", alignItems:\"center\" }}>\n                {q}\n                <span style={{ color:C.purple, fontSize:18, fontWeight:400, flexShrink:0, marginLeft:12 }}>+</span>\n              </summary>\n              <div style={{ padding:\"0 20px 18px\", fontSize:14, color:C.muted, lineHeight:1.65 }}>{a}</div>\n            </details>\n          ))}\n        </div>\n      </section>\n\n      {/* CTA */}\n      <section style={{ background:\"linear-gradient(160deg,#2D1B69,#0D0625)\", padding:\"80px 24px\", textAlign:\"center\" }}>\n        <h2 style={{ fontFamily:\"'Fraunces',Georgia,serif\", fontSize:\"clamp(28px,5vw,48px)\", fontWeight:500, color:\"#fff\", margin:\"0 0 16px\", letterSpacing:\"-0.03em\" }}>\n          Ready to start?\n        </h2>\n        <p style={{ fontSize:16, color:\"rgba(255,255,255,0.55)\", marginBottom:36 }}>Free forever. No card needed.</p>\n        <Link href=\"/auth/register\" style={{ display:\"inline-flex\", alignItems:\"center\", gap:8, padding:\"14px 32px\", borderRadius:14, background:\"#fff\", color:C.navy, textDecoration:\"none\", fontSize:14, fontWeight:700, boxShadow:\"0 8px 24px rgba(0,0,0,0.2)\" }}>\n          Start free <ArrowRight size={14}/>\n        </Link>\n      </section>\n\n      <style>{`\n        @media(max-width:768px){ .plans-grid{grid-template-columns:1fr!important;} }\n        details summary::-webkit-details-marker{display:none}\n        details[open] summary span{transform:rotate(45deg);}\n        details summary span{transition:transform 0.2s;display:inline-block;}\n      `}</style>\n    </div>\n  );\n}\n","frontend/src/app/(marketing)/how-it-works/page.tsx":"import Link from \"next/link\";\nimport { ArrowRight, Zap, Package, Store, TrendingUp, Check } from \"lucide-react\";\n\nconst C = { bg:\"#F4F2FB\", navy:\"#130D2E\", purple:\"#6B35E8\", muted:\"rgba(19,13,46,0.5)\", border:\"rgba(107,53,232,0.1)\", faint:\"rgba(107,53,232,0.04)\" };\n\nconst STEPS = [\n  {\n    n:1, icon:Store, color:\"#6B35E8\",\n    title:\"Create your account\",\n    desc:\"Sign up in 30 seconds. Pick your niche, choose a store template, and your store is live immediately — no design skills needed.\",\n    details:[\"Choose from 29 industry templates\",\"Custom domain (your own brand)\",\"Mobile-optimised storefront\",\"Full KIRO AI from day one\"],\n  },\n  {\n    n:2, icon:Package, color:\"#0EA5E9\",\n    title:\"Import products instantly\",\n    desc:\"Paste any product URL from AliExpress, Temu, Amazon, or CJDropshipping. KIRO scores it A–F, rewrites the description, and sets a profitable price.\",\n    details:[\"Paste any supplier URL\",\"KIRO grades every product A–F\",\"Auto-pricing for healthy margins\",\"Bulk import entire stores\"],\n  },\n  {\n    n:3, icon:Zap, color:\"#10B981\",\n    title:\"KIRO runs your store\",\n    desc:\"KIRO monitors your store 24/7. It alerts you to opportunities, writes your marketing copy, and handles customer queries — automatically.\",\n    details:[\"Daily revenue insights\",\"Flash sale automation\",\"Abandoned cart recovery\",\"Product description writing\"],\n  },\n  {\n    n:4, icon:TrendingUp, color:\"#F59E0B\",\n    title:\"Get paid, grow fast\",\n    desc:\"Accept payments via Paystack (card, bank transfer, USSD) and Stripe. Money hits your account directly — no middleman, no delay.\",\n    details:[\"Paystack for local payments\",\"Stripe for international orders\",\"Automatic order fulfilment via CJ\",\"Real-time revenue tracking\"],\n  },\n];\n\nexport default function HowItWorksPage() {\n  return (\n    <div style={{ fontFamily:\"'Plus Jakarta Sans',system-ui,sans-serif\" }}>\n      <style>{`@import url('https://fonts.googleapis.com/css2?family=Fraunces:ital,wght@0,400;0,500;1,400;1,500&family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&display=swap');`}</style>\n\n      {/* Hero */}\n      <section style={{ padding:\"80px 24px 60px\", textAlign:\"center\", maxWidth:680, margin:\"0 auto\" }}>\n        <p style={{ fontSize:11, fontWeight:700, letterSpacing:\"0.12em\", color:C.purple, marginBottom:12, textTransform:\"uppercase\" }}>HOW IT WORKS</p>\n        <h1 style={{ fontFamily:\"'Fraunces',Georgia,serif\", fontSize:\"clamp(36px,6vw,56px)\", fontWeight:500, letterSpacing:\"-0.04em\", color:C.navy, margin:\"0 0 16px\", lineHeight:1.08 }}>\n          From zero to<br/><em style={{ fontStyle:\"italic\", color:C.purple }}>first sale.</em>\n        </h1>\n        <p style={{ fontSize:16, color:C.muted, margin:\"0 auto\", lineHeight:1.6, maxWidth:460 }}>\n          Four steps. Sixty seconds to launch. Everything else runs itself.\n        </p>\n      </section>\n\n      {/* Steps */}\n      <section style={{ maxWidth:900, margin:\"0 auto\", padding:\"0 24px 80px\" }}>\n        <div style={{ display:\"flex\", flexDirection:\"column\", gap:3 }}>\n          {STEPS.map((step, idx) => {\n            const Icon = step.icon;\n            return (\n              <div key={step.n} style={{\n                display:\"grid\", gridTemplateColumns:\"1fr 1fr\", gap:40, alignItems:\"center\",\n                padding:\"56px 48px\", background:\"#fff\", borderRadius:24,\n                border:`1px solid ${C.border}`, boxShadow:\"0 2px 16px rgba(107,53,232,0.04)\",\n                direction: idx%2===1?\"rtl\":\"ltr\",\n              }} className=\"step-row\">\n                {/* Text */}\n                <div style={{ direction:\"ltr\" }}>\n                  <div style={{ display:\"flex\", alignItems:\"center\", gap:12, marginBottom:20 }}>\n                    <div style={{ width:40, height:40, borderRadius:12, background:`${step.color}12`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                      <Icon size={18} color={step.color}/>\n                    </div>\n                    <span style={{ fontSize:11, fontWeight:800, letterSpacing:\"0.1em\", color:step.color, textTransform:\"uppercase\" }}>Step {step.n}</span>\n                  </div>\n                  <h2 style={{ fontFamily:\"'Fraunces',Georgia,serif\", fontSize:\"clamp(24px,3.5vw,34px)\", fontWeight:500, color:C.navy, margin:\"0 0 14px\", letterSpacing:\"-0.03em\", lineHeight:1.15 }}>\n                    {step.title}\n                  </h2>\n                  <p style={{ fontSize:15, color:C.muted, lineHeight:1.65, margin:\"0 0 24px\" }}>{step.desc}</p>\n                  <div style={{ display:\"flex\", flexDirection:\"column\", gap:8 }}>\n                    {step.details.map(d => (\n                      <div key={d} style={{ display:\"flex\", alignItems:\"center\", gap:8 }}>\n                        <Check size={13} color={step.color} strokeWidth={2.5}/>\n                        <span style={{ fontSize:13, color:C.muted, fontWeight:500 }}>{d}</span>\n                      </div>\n                    ))}\n                  </div>\n                </div>\n\n                {/* Visual */}\n                <div style={{ direction:\"ltr\" }}>\n                  <div style={{\n                    aspectRatio:\"4/3\", borderRadius:20,\n                    background:`linear-gradient(135deg,${step.color}08,${step.color}18)`,\n                    border:`1px solid ${step.color}20`,\n                    display:\"flex\", alignItems:\"center\", justifyContent:\"center\",\n                  }}>\n                    <div style={{ textAlign:\"center\" }}>\n                      <div style={{ width:80, height:80, borderRadius:24, background:`${step.color}15`, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", margin:\"0 auto 16px\" }}>\n                        <Icon size={36} color={step.color}/>\n                      </div>\n                      <span style={{ fontSize:32, fontWeight:900, color:step.color, display:\"block\", lineHeight:1 }}>0{step.n}</span>\n                      <span style={{ fontSize:12, color:`${step.color}80`, fontWeight:600, marginTop:4, display:\"block\" }}>{step.title}</span>\n                    </div>\n                  </div>\n                </div>\n              </div>\n            );\n          })}\n        </div>\n      </section>\n\n      {/* Stats */}\n      <section style={{ background:\"#fff\", padding:\"64px 24px\", borderTop:`1px solid ${C.border}` }}>\n        <div style={{ maxWidth:800, margin:\"0 auto\", display:\"grid\", gridTemplateColumns:\"repeat(4,1fr)\", gap:32, textAlign:\"center\" }} className=\"stats-g\">\n          {[\n            { n:\"60s\",   l:\"To launch a store\"   },\n            { n:\"29\",    l:\"Store templates\"      },\n            { n:\"22\",    l:\"KIRO commands\"         },\n            { n:\"50+\",   l:\"Payment currencies\"   },\n          ].map(s => (\n            <div key={s.l}>\n              <p style={{ fontFamily:\"'Fraunces',Georgia,serif\", fontSize:\"clamp(32px,5vw,48px)\", fontWeight:500, color:C.navy, margin:\"0 0 6px\", letterSpacing:\"-0.04em\" }}>{s.n}</p>\n              <p style={{ fontSize:13, color:C.muted, margin:0 }}>{s.l}</p>\n            </div>\n          ))}\n        </div>\n      </section>\n\n      {/* CTA */}\n      <section style={{ padding:\"80px 24px\", textAlign:\"center\", background:\"linear-gradient(160deg,#2D1B69,#0D0625)\" }}>\n        <h2 style={{ fontFamily:\"'Fraunces',Georgia,serif\", fontSize:\"clamp(28px,5vw,48px)\", fontWeight:500, color:\"#fff\", margin:\"0 0 14px\", letterSpacing:\"-0.03em\" }}>\n          Ready to see it live?\n        </h2>\n        <p style={{ fontSize:15, color:\"rgba(255,255,255,0.5)\", marginBottom:36 }}>Your store is 60 seconds away. Free forever.</p>\n        <Link href=\"/auth/register\" style={{ display:\"inline-flex\", alignItems:\"center\", gap:8, padding:\"14px 32px\", borderRadius:14, background:\"#fff\", color:C.navy, textDecoration:\"none\", fontSize:14, fontWeight:700, boxShadow:\"0 8px 24px rgba(0,0,0,0.2)\" }}>\n          Launch your store free <ArrowRight size={14}/>\n        </Link>\n      </section>\n\n      <style>{`\n        @media(max-width:768px){ .step-row{grid-template-columns:1fr!important;direction:ltr!important;padding:32px 24px!important;} .stats-g{grid-template-columns:1fr 1fr!important;} }\n      `}</style>\n    </div>\n  );\n}\n","frontend/src/app/(marketing)/layout.tsx":"\"use client\";\nimport Link from \"next/link\";\nimport { usePathname } from \"next/navigation\";\nimport { useState, useEffect } from \"react\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { Menu, X, ArrowRight } from \"lucide-react\";\n\n// Unified color system matching auth + dashboard + landing page\nconst C = {\n  bg:     \"#F4F2FB\",\n  navy:   \"#130D2E\",\n  purple: \"#6B35E8\",\n  muted:  \"rgba(19,13,46,0.5)\",\n  border: \"rgba(107,53,232,0.1)\",\n};\n\nconst NAV_LINKS = [\n  { href: \"/features\",     label: \"Features\"     },\n  { href: \"/pricing\",      label: \"Pricing\"      },\n  { href: \"/how-it-works\", label: \"How it works\" },\n  { href: \"/about\",        label: \"About\"        },\n];\n\nconst FOOTER = [\n  {\n    title: \"Product\",\n    links: [\n      [\"Features\",     \"/features\"     ],\n      [\"How it Works\", \"/how-it-works\" ],\n      [\"Pricing\",      \"/pricing\"      ],\n      [\"Security\",     \"/security\"     ],\n    ],\n  },\n  {\n    title: \"Company\",\n    links: [\n      [\"About\",   \"/about\"   ],\n      [\"Contact\", \"/contact\" ],\n    ],\n  },\n  {\n    title: \"Legal\",\n    links: [\n      [\"Privacy Policy\", \"/privacy\" ],\n      [\"Terms of Use\",   \"/terms\"   ],\n      [\"Cookie Policy\",  \"/cookies\" ],\n    ],\n  },\n];\n\nfunction Logo() {\n  return (\n    <Link href=\"/\" style={{ display:\"flex\", alignItems:\"center\", gap:10, textDecoration:\"none\" }}>\n      <div style={{\n        width:32, height:32, borderRadius:9,\n        background:\"linear-gradient(145deg,#2D1B69,#0D0625)\",\n        display:\"flex\", alignItems:\"center\", justifyContent:\"center\",\n        boxShadow:\"0 4px 12px rgba(45,27,105,0.3)\",\n      }}>\n        <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\">\n          <path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"white\"/>\n        </svg>\n      </div>\n      <span style={{ fontSize:16, fontWeight:800, color:C.navy, letterSpacing:\"-0.02em\" }}>\n        Drop<span style={{ color:C.purple }}>OS</span>\n      </span>\n    </Link>\n  );\n}\n\nfunction Nav() {\n  const pathname = usePathname();\n  const [scrolled, setScrolled] = useState(false);\n  const [open, setOpen] = useState(false);\n\n  useEffect(() => {\n    const fn = () => setScrolled(window.scrollY > 20);\n    window.addEventListener(\"scroll\", fn, { passive:true });\n    return () => window.removeEventListener(\"scroll\", fn);\n  }, []);\n  useEffect(() => { setOpen(false); }, [pathname]);\n\n  return (\n    <>\n      <header style={{\n        position:\"fixed\", top:0, left:0, right:0, zIndex:100,\n        height:64, display:\"flex\", alignItems:\"center\",\n        padding:\"0 24px\",\n        background: scrolled ? \"rgba(244,242,251,0.95)\" : \"transparent\",\n        backdropFilter: scrolled ? \"blur(20px)\" : \"none\",\n        borderBottom: scrolled ? `1px solid ${C.border}` : \"1px solid transparent\",\n        transition:\"all 0.25s ease\",\n      }}>\n        <Logo />\n\n        {/* Desktop links */}\n        <nav style={{ flex:1, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:4 }} className=\"mkt-nav\">\n          {NAV_LINKS.map(l => (\n            <Link key={l.href} href={l.href}\n              style={{\n                fontSize:13, fontWeight:500, textDecoration:\"none\", padding:\"7px 14px\", borderRadius:9,\n                color: pathname === l.href ? C.navy : C.muted,\n                background: pathname === l.href ? \"rgba(107,53,232,0.06)\" : \"transparent\",\n                transition:\"all 0.15s\",\n              }}\n              onMouseEnter={e => { e.currentTarget.style.color=C.navy; e.currentTarget.style.background=\"rgba(107,53,232,0.06)\"; }}\n              onMouseLeave={e => {\n                e.currentTarget.style.color = pathname===l.href ? C.navy : C.muted;\n                e.currentTarget.style.background = pathname===l.href ? \"rgba(107,53,232,0.06)\" : \"transparent\";\n              }}>\n              {l.label}\n            </Link>\n          ))}\n        </nav>\n\n        {/* CTA */}\n        <div style={{ display:\"flex\", alignItems:\"center\", gap:10 }} className=\"mkt-cta\">\n          <Link href=\"/auth/login\" style={{ fontSize:13, fontWeight:600, color:C.muted, textDecoration:\"none\", padding:\"8px 14px\", borderRadius:8, transition:\"color 0.15s\" }}>\n            Sign in\n          </Link>\n          <Link href=\"/auth/register\" style={{\n            display:\"flex\", alignItems:\"center\", gap:6,\n            fontSize:13, fontWeight:700, color:\"#fff\", textDecoration:\"none\",\n            padding:\"9px 18px\", borderRadius:10,\n            background:C.navy,\n            boxShadow:\"0 4px 14px rgba(19,13,46,0.18)\",\n          }}>\n            Start free <ArrowRight size={13}/>\n          </Link>\n        </div>\n\n        {/* Mobile hamburger */}\n        <button onClick={() => setOpen(!open)} className=\"mkt-burger\"\n          style={{ display:\"none\", background:\"none\", border:\"none\", cursor:\"pointer\", color:C.navy, padding:4, marginLeft:\"auto\" }}>\n          {open ? <X size={22}/> : <Menu size={22}/>}\n        </button>\n      </header>\n\n      {/* Mobile menu */}\n      <AnimatePresence>\n        {open && (\n          <motion.div initial={{ opacity:0, y:-8 }} animate={{ opacity:1, y:0 }} exit={{ opacity:0, y:-8 }}\n            style={{\n              position:\"fixed\", top:64, left:0, right:0, zIndex:99,\n              background:\"rgba(244,242,251,0.98)\", backdropFilter:\"blur(20px)\",\n              borderBottom:`1px solid ${C.border}`, padding:\"16px 24px 24px\",\n              display:\"flex\", flexDirection:\"column\", gap:4,\n            }}>\n            {NAV_LINKS.map(l => (\n              <Link key={l.href} href={l.href} onClick={() => setOpen(false)}\n                style={{ fontSize:15, fontWeight:600, color:C.navy, textDecoration:\"none\", padding:\"12px 0\", borderBottom:`1px solid ${C.border}` }}>\n                {l.label}\n              </Link>\n            ))}\n            <Link href=\"/auth/register\" onClick={() => setOpen(false)}\n              style={{ marginTop:12, display:\"flex\", alignItems:\"center\", justifyContent:\"center\", gap:6, padding:\"14px 0\", borderRadius:12, background:C.navy, color:\"#fff\", textDecoration:\"none\", fontSize:15, fontWeight:700 }}>\n              Start free <ArrowRight size={14}/>\n            </Link>\n          </motion.div>\n        )}\n      </AnimatePresence>\n\n      <style>{`\n        @media(max-width:768px){ .mkt-nav,.mkt-cta{display:none!important;} .mkt-burger{display:flex!important;} }\n      `}</style>\n    </>\n  );\n}\n\nfunction Footer() {\n  return (\n    <footer style={{ background:\"#fff\", borderTop:`1px solid ${C.border}`, paddingTop:56, paddingBottom:32, fontFamily:\"'Plus Jakarta Sans',system-ui,sans-serif\" }}>\n      <div style={{ maxWidth:1080, margin:\"0 auto\", padding:\"0 24px\" }}>\n        <div style={{ display:\"grid\", gridTemplateColumns:\"2fr 1fr 1fr 1fr\", gap:40, marginBottom:48 }} className=\"footer-grid\">\n          {/* Brand */}\n          <div>\n            <Logo />\n            <p style={{ fontSize:13, color:C.muted, marginTop:14, lineHeight:1.65, maxWidth:240 }}>\n              The AI-powered commerce platform. Launch your store in 60 seconds.\n            </p>\n            <div style={{ display:\"flex\", alignItems:\"center\", gap:6, marginTop:16 }}>\n              <div style={{ width:7, height:7, borderRadius:\"50%\", background:\"#10B981\" }}/>\n              <span style={{ fontSize:11, color:\"rgba(19,13,46,0.4)\", fontWeight:500 }}>All systems operational</span>\n            </div>\n          </div>\n\n          {/* Link columns */}\n          {FOOTER.map(col => (\n            <div key={col.title}>\n              <p style={{ fontSize:11, fontWeight:700, letterSpacing:\"0.1em\", color:C.muted, textTransform:\"uppercase\", marginBottom:16 }}>\n                {col.title}\n              </p>\n              <div style={{ display:\"flex\", flexDirection:\"column\", gap:10 }}>\n                {col.links.map(([label, href]) => (\n                  <Link key={label} href={href}\n                    style={{ fontSize:13, color:C.muted, textDecoration:\"none\", fontWeight:500, transition:\"color 0.15s\" }}\n                    onMouseEnter={e => e.currentTarget.style.color=C.navy}\n                    onMouseLeave={e => e.currentTarget.style.color=C.muted}>\n                    {label}\n                  </Link>\n                ))}\n              </div>\n            </div>\n          ))}\n        </div>\n\n        <div style={{ borderTop:`1px solid ${C.border}`, paddingTop:24, display:\"flex\", alignItems:\"center\", justifyContent:\"space-between\", flexWrap:\"wrap\", gap:12 }}>\n          <p style={{ fontSize:12, color:C.muted }}>© 2026 DropOS. All rights reserved.</p>\n          <p style={{ fontSize:12, color:C.muted }}>Built for merchants who move fast 🚀</p>\n        </div>\n      </div>\n\n      <style>{`@media(max-width:768px){ .footer-grid{grid-template-columns:1fr 1fr!important; gap:32px!important;} }`}</style>\n    </footer>\n  );\n}\n\nexport default function MarketingLayout({ children }: { children: React.ReactNode }) {\n  return (\n    <div style={{ background:C.bg, minHeight:\"100vh\", fontFamily:\"'Plus Jakarta Sans',system-ui,sans-serif\" }}>\n      <style>{`\n        @import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&family=Fraunces:ital,wght@0,400;0,500;0,600;0,700;1,400;1,500;1,600;1,700&display=swap');\n        *{box-sizing:border-box;}\n      `}</style>\n      <Nav />\n      <main style={{ paddingTop:64 }}>\n        {children}\n      </main>\n      <Footer />\n    </div>\n  );\n}\n"};
for(const[rel,c]of Object.entries(files)){const p=rel.split('/').join(path.sep);fs.mkdirSync(path.dirname(p),{recursive:true});fs.writeFileSync(p,c,'utf8');console.log('✓',rel.split('/').slice(-2).join('/'));}
try{execSync('git add .',{stdio:'inherit'});const st=execSync('git status --short',{encoding:'utf8'}).trim();if(st){execSync('git commit -m "fix: white text on light bg across all marketing pages"',{stdio:'inherit'});}execSync('git push origin main',{stdio:'inherit'});console.log('\n✅ Pushed!');process.chdir('frontend');execSync('vercel --prod --force',{stdio:'inherit'});console.log('\n🚀 LIVE');}catch(e){console.log(e.message);}